// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

class LmdbStatementAccessArbiterTest {

	@Test
	void adjacencyIsTheStructuralPreferenceUntilLmdbStrictlyDominates() {
		assertThat(LmdbStatementAccessArbiter.choose(10, 10, 10, 10))
				.isEqualTo(LmdbStatementAccessArbiter.Source.ADJACENCY);
		assertThat(LmdbStatementAccessArbiter.choose(5, 20, 10, 30))
				.isEqualTo(LmdbStatementAccessArbiter.Source.ADJACENCY);
		assertThat(LmdbStatementAccessArbiter.choose(0, Double.POSITIVE_INFINITY, 0,
				Double.POSITIVE_INFINITY))
						.isEqualTo(LmdbStatementAccessArbiter.Source.ADJACENCY);
		assertThat(LmdbStatementAccessArbiter.choose(100, 120, 5, 20))
				.isEqualTo(LmdbStatementAccessArbiter.Source.LMDB);
	}

	@Test
	void warmedRuntimeEvidenceCanOverrideTheStructuralPreference() {
		assertThat(LmdbStatementAccessArbiter.choose(10, 20, 10, 20,
				100, 120, 5, 20, true))
						.isEqualTo(LmdbStatementAccessArbiter.Source.LMDB);
	}

	@Test
	void candidateArgumentOrderDoesNotAffectSelection() {
		assertThat(LmdbStatementAccessArbiter.choose(
				LmdbStatementAccessArbiter.Source.ADJACENCY, 100, 120,
				LmdbStatementAccessArbiter.Source.LMDB, 5, 20))
						.isEqualTo(LmdbStatementAccessArbiter.Source.LMDB);
		assertThat(LmdbStatementAccessArbiter.choose(
				LmdbStatementAccessArbiter.Source.LMDB, 5, 20,
				LmdbStatementAccessArbiter.Source.ADJACENCY, 100, 120))
						.isEqualTo(LmdbStatementAccessArbiter.Source.LMDB);
	}

	@Test
	void onlyTheWinningCandidateIsOpened() throws Exception {
		AtomicInteger adjacencyOpens = new AtomicInteger();
		AtomicInteger lmdbOpens = new AtomicInteger();
		RecordIterator winner = LmdbStatementAccessArbiter.open(
				LmdbStatementAccessArbiter.Source.ADJACENCY,
				() -> {
					adjacencyOpens.incrementAndGet();
					return EmptyRecordIterator.INSTANCE;
				},
				() -> {
					lmdbOpens.incrementAndGet();
					return EmptyRecordIterator.INSTANCE;
				});
		winner.close();

		assertThat(adjacencyOpens).hasValue(1);
		assertThat(lmdbOpens).hasValue(0);
	}

	@Test
	void earlyCloseIsCensoredRatherThanCompletedEvidence() {
		LmdbStatementAccessArbiter.RuntimeEvidence evidence = new LmdbStatementAccessArbiter.RuntimeEvidence();
		int variantKey = 0;
		RecordIterator measured = LmdbStatementAccessArbiter.measured(new RecordIterator() {
			private boolean emitted;

			@Override
			public long[] next() {
				if (emitted) {
					return null;
				}
				emitted = true;
				return new long[4];
			}

			@Override
			public void close() {
			}
		}, evidence, variantKey, 0L, 2D);

		assertThat(measured.next()).isNotNull();
		measured.close();

		assertThat(evidence.completedCount(variantKey)).isZero();
		assertThat(evidence.censoredCount(variantKey)).isOne();
	}

	@Test
	void warmedEvidenceDoesNotCrossAdjacencyPublicationRegimes() throws Exception {
		LmdbStatementAccessArbiter.RuntimeEvidence evidence = new LmdbStatementAccessArbiter.RuntimeEvidence();
		int adjacencyKey = 0;
		int lmdbKey = 1;
		for (int sample = 0; sample < 8; sample++) {
			evidence.completed(17L, adjacencyKey, 1_000L, 1D);
			evidence.completed(17L, lmdbKey, 10L, 1D);
		}
		assertThat(evidence.choose(17L, 10D, 20D, adjacencyKey, 1D, 10D, 20D, lmdbKey, 1D))
				.isEqualTo(LmdbStatementAccessArbiter.Source.LMDB);

		assertThat(evidence.choose(18L, 10D, 20D, adjacencyKey, 1D, 10D, 20D, lmdbKey, 1D))
				.isEqualTo(LmdbStatementAccessArbiter.Source.ADJACENCY);
		evidence.completed(17L, lmdbKey, 1L, 1D);
		assertThat(evidence.choose(18L, 10D, 20D, adjacencyKey, 1D, 10D, 20D, lmdbKey, 1D))
				.isEqualTo(LmdbStatementAccessArbiter.Source.ADJACENCY);
	}
}
